                <div class="mx-auto mb-6 flex w-10 h-10 md:w-12 md:h-12 lg:h-16 lg:w-16 items-center justify-center rounded-2xl bg-gradient-to-br from-pink-500 to-rose-600 shadow-lg shadow-pink-500/20 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-[-3deg]">
                    <svg class="h-5 w-5 md:h-7 md:w-7 text-pink-100" fill="none" stroke="currentColor" stroke-width="1.8" viewBox="0 0 24 24">
